Record pv_res := mkPV { pv_adv : Z ; pv_result : option Z ; pv_err : option (Z * Z) }.

Definition pv_out (bs : list byte) : pv_res :=
  match bs with
  | c0 :: c1 :: c2 :: c3 :: c4 :: c5 :: c6 :: c7 :: _ =>
      if negb (zb c0 =? 72) then mkPV 1 None (Some (HE_BAD_VERSION, ALOC_PV_H)) else
      if negb (zb c1 =? 84) then mkPV 2 None (Some (HE_BAD_VERSION, ALOC_PV_T1)) else
      if negb (zb c2 =? 84) then mkPV 3 None (Some (HE_BAD_VERSION, ALOC_PV_T2)) else
      if negb (zb c3 =? 80) then mkPV 4 None (Some (HE_BAD_VERSION, ALOC_PV_P)) else
      if negb (zb c4 =? 47) then mkPV 5 None (Some (HE_BAD_VERSION, ALOC_PV_SLASH)) else
      if negb (is_digitc (zb c5)) then mkPV 5 None (Some (HE_BAD_VERSION, ALOC_PV_D1)) else
      if negb (zb c6 =? 46) then mkPV 7 (Some (10 * (zb c5 - 48))) (Some (HE_BAD_VERSION, ALOC_PV_DOT)) else
      if negb (is_digitc (zb c7)) then mkPV 7 (Some (10 * (zb c5 - 48))) (Some (HE_BAD_VERSION, ALOC_PV_D2)) else
      mkPV 8 (Some (10 * (zb c5 - 48) + (zb c7 - 48))) None
  | _ => mkPV 0 None (Some (HE_NEED_MORE, ALOC_PV_NM))
  end.

Definition pv_result_cell (r : pv_res) (r0 : Z) : Z := match pv_result r with Some v => v | None => r0 end.
Definition pv_ec (r : pv_res) (E0 : ecv) : ecv := match pv_err r with Some (e, loc) => EC_http_loc e loc | None => E0 end.
Definition pv_cat (r : pv_res) (g : bool) : bool := match pv_err r with Some _ => true | None => g end.

