(* [comment removed for export] *)
Definition PV_STACK : Z := 64 + AASSIGN_STACK.

Definition pv_W (lo : Z) (sp : word) (I R E : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (I, I + 8); (R, R + 4); (E, E + 24); (AG_HTTP_CAT, AG_HTTP_CAT + 64)]%Z.

Definition pv_post_r (r : pv_res) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (q I R E lo shi : Z) (bs : list byte) (r0 : Z) (E0 : ecv) (g : bool) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch (pv_W lo sp I R E) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ bytes_at bsegs m' q bs
    /\ rw_cells bsegs m' I [C8 (wz (q + pv_adv r))]
    /\ rw_cells bsegs m' R [C4 (wz (pv_result_cell r r0))]
    /\ rw_cells bsegs m' E (ErrCodeCells (pv_ec r E0))
    /\ AHttpCat m' (pv_cat r g) /\ AXStatics m'
    /\ ACONST m' /\ stack0 m' lo shi.                                  (* [comment removed for export] *)

Definition pv_post := fun ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc q I R E lo shi bs r0 E0 g m =>
  pv_post_r (pv_out bs) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc q I R E lo shi bs r0 E0 g m.

(* [comment removed for export] *)
Definition pv_pure (sp : word) (q I R E lo shi : Z) (bs : list byte) (r0 : Z) (E0 : ecv) : Prop :=
  ec_ok E0 /\ 0 <= r0 < 2^32 /\ lo + PV_STACK <= bv_unsigned sp /\ aceil <= lo
  /\ aapp q (Z.of_nat (length bs)) /\ q + Z.of_nat (length bs) <= lo
  /\ bv_unsigned sp <= I /\ I + 8 <= shi /\ I mod 8 = 0
  /\ bv_unsigned sp <= R /\ R + 4 <= shi /\ R mod 4 = 0
  /\ aapp E 24 /\ E mod 8 = 0
  /\ (I + 8 <= R \/ R + 4 <= I) /\ (q + Z.of_nat (length bs) <= E \/ E + 24 <= q)
  /\ bv_unsigned sp mod 16 = 0 /\ bv_unsigned sp + 64 <= shi.

Definition pv_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (q I R E lo shi : Z) (bs : list byte) (r0 : Z) (E0 : ecv) (g : bool),
  bytes_at bsegs m q bs ->
  rw_cells bsegs m I [C8 (wz q)] ->
  rw_cells bsegs m R [C4 (wz r0)] ->
  rw_cells bsegs m E (ErrCodeCells E0) ->
  AHttpCat m g -> AXStatics m ->
  stk bsegs m lo (bv_unsigned sp) ->
  pv_pure sp q I R E lo shi bs r0 E0 ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  ACONST m -> stack0 m lo shi ->
  accessible m q (Z.of_nat (length bs)) -> accessible m E 24 -> shvis m E (E + 24) ->
  evt bsegs (pv_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc q I R E lo shi bs r0 E0 g m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz I) (wz (q + Z.of_nat (length bs))) (wz R) (wz E) a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_BP_PARSE_VERSION) fc None m (seg_rom bsegs)).

