Lemma pv_tail : forall rax ra sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s0v s1v s2v s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (q I R E lo shi : Z) (bs : list byte) (itv resv r0 : Z) (E0 : ecv) (g : bool)
    (j8 : list byte) (e loc : Z) (r : pv_res),
  pv_tctx m m1 sp s0v s1v s2v ra q I R E lo shi bs itv resv E0 j8 e ->
  pv_pure sp q I R E lo shi bs r0 E0 ->
  1 <= e < 2^31 -> 0 <= loc -> loc + 1 < 2^64 ->
  q + pv_adv r = itv -> pv_result_cell r r0 = resv -> pv_err r = Some (e, loc) -> 0 <= resv < 2^32 ->
  evt bsegs (pv_post_r r ra sp gp tp s0v s1v s2v s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc q I R E lo shi bs r0 E0 g m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (wz E) (wz ASHADOW_BASE) (wz (E + 16)) a1 a2 a3 a4 a5 a6 a7
              (wz (loc + 1)) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0xd3fbc) fc None m1 (seg_rom bsegs)).
