Definition pv_exit_stmt (pc e loc : Z) : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s0v s1v s2v s2x s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (q I R E lo shi : Z) (bs : list byte) (itv resv r0 : Z) (E0 : ecv) (g : bool)
    (j8 junk : list byte) (r : pv_res),
  pv_ctx m m1 sp s0v s1v s2v ra q I R E lo shi bs itv resv E0 g j8 junk ->
  pv_pure sp q I R E lo shi bs r0 E0 ->
  q + pv_adv r = itv -> pv_result_cell r r0 = resv -> pv_err r = Some (e, loc) -> 0 <= resv < 2^32 ->
  evt bsegs (pv_post_r r ra sp gp tp s0v s1v s2v s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc q I R E lo shi bs r0 E0 g m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (wz E) (wz ASHADOW_BASE) a0 a1 a2 a3 a4 a5 a6 a7
              s2x s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom bsegs)).

Local Ltac pv_exit_tac e loc :=
  unfold pv_exit_stmt;
  intros rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s0v s1v s2v s2x s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    F fc m m1 q I R E lo shi bs itv resv r0 E0 g j8 junk r;
  intros CTX PURE ADV RESV ERR RV;
  destruct CTX as (FR0 & TMP & FRhi & IT & RES & EC & ST & WIN & MU & WM & MI & MU2 & HC & SIDE);
  pose proof PURE as PURE';
  destruct PURE' as (EOK & R0 & LO & CEIL & APP & QHI & ILO & IHI & IAL & RLO & RHI & RAL & APE & EAL & DIR & DQE & SPAL & SHI);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (aapp_bounds _ 24 APE ltac:(lia)) as (EB1 & EB2 & EB3 & EB4 & EB5);
  pose proof (aapp_bounds _ _ APP ltac:(lia)) as (PB1 & PB2 & PB3 & PB4 & PB5);
  pose proof aceil_facts as (AF1 & AF2 & AF3);
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  (* [comment removed for export] *)
  pose proof (pv_cat_now _ _ _ _ _ _ _ HC MU2 WM CEIL ILO RLO ltac:(unfold PV_STACK, AASSIGN_STACK, AINTRIN_STACK in LO; lia)) as HC1;
  clear MU2 HC;
  destruct (pv_side_now _ _ _ _ _ _ _ _ _ _ _ _ SIDE MU WM PURE) as (AC1 & SK1 & XS1 & _);
  pose proof (stack0_bounds _ _ _ SK1) as [SKB1 SKB2];
