            cbn [disjoint_from fst snd]; unfold AG_HTTP_CAT, AG_HTTP_CAT_GUARD; clear - AF1 CEIL LO EB1; repeat split; lia);
      clear HC2 MU3 WM3;
      (* [comment removed for export] *)
      step;
      pose proof (accessible_read0_sr m3 E 24 (E + 16) AE3 ltac:(lia) ltac:(clear - EAL; unhideL; Z.div_mod_to_equations; lia) ltac:(lia)) as RD;
      shchk_fast RD; clear AE3;
      join_frameA TMPa TMPb (bv_unsigned sp + -56); join_frameA DST3 ECb E;
      eapply (pv_tail _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ m m3 q I R E lo shi bs itv resv r0 E0 g j8 e loc r);
      [ unfold pv_tctx, pv_W, AG_HTTP_CAT, wz; repeat (split; [fast_eassumption|]); fast_eassumption
      | exact PURE | clear; lia | clear; vm_compute; intro; discriminate | clear; vm_compute; reflexivity
      | exact ADV | exact RESV | exact ERR | exact RV ]
    end
  end.
